<script setup>
const props = defineProps({
  selectable: {
    type: Array,
    required: true
  },
  selected: {
    type: String,
    default: null
  },
  onClickGoTo: {
    type: [Object, Boolean],
    default: false
  }
})

const emit = defineEmits(['select'])
const { link } = useUtils()

onMounted(() => {
  // Select all IDs in props.selectable
  props.selectable.forEach(id => {
    const el = document.getElementById(id)
    if (el) {
      el.classList.add('selectable')
      // make it focusable for accessibility
      el.setAttribute('tabindex', '0')
      // add aria label
      el.setAttribute('aria-label', `Select ${id}`)
      // add click event listener
      el.addEventListener('click', async () => {
        selected.value = id
        emit('select', id)
        // Remove selected class from all selectable elements
        document.querySelectorAll('.selectable').forEach(el => el.classList.remove('selected'))
        // Add selected class to clicked element
        el.classList.add('selected')
        // Go to page if onClickGoTo is set
        if (props.onClickGoTo) {
          return await navigateTo({ path: link(props.onClickGoTo), query: { country: id }, hash: '#profiles' })
        } else {
          // Scroll to profiles section
          const profilesSection = document.getElementById('profiles')
          if (profilesSection) {
            profilesSection.scrollIntoView({ behavior: 'smooth' })
          }
        }
      })
    }
  })
})

const selected = ref(props.selected)

watch(() => props.selected, (newVal) => {
  selected.value = newVal
  // Update selected class on elements
  document.querySelectorAll('.selectable').forEach(el => {
    if (el.id === newVal) {
      el.classList.add('selected')
    } else {
      el.classList.remove('selected')
    }
  })
})
</script>

