<style scoped>
  .land {
    fill: var(--color-primary-soft);
  }

  .border {
    fill: var(--color-primary);
  }

  .selectable {
    cursor: pointer;

    .land {
      fill: color-mix(in srgb, var(--color-primary) 50%, var(--color-primary-soft) 50%);
      transition: .5s ease;
    }

    &:hover .land {
      fill: var(--color-primary);
    }

    &:focus {
      outline: none;
    }

    &:focus-visible {
      outline: 3px solid var(--color-yellow);
      outline-offset: 2px;
    }
  }

  .selected,
  .selected:hover {
    .land {
      fill: var(--color-yellow);
    }
  }

  .mask {
    clip-path: url(#clippath);
  }
</style>